<?php
declare(strict_types=1);
namespace App\Services;
use App\Services\Fiscal\FiscalDecimal;
use App\Services\Fiscal\FiscalIssueDateService;
use RuntimeException;
final class PaymentComplementFiscalSnapshotService
{
 public function __construct(private$db){}
 public function compose(int$id):array{$c=$this->db->table('payment_complements')->where(['id'=>$id,'deleted'=>0])->get(1)->getRow();if(!$c||!in_array($c->status,['draft','complete_draft','stamped'],true))throw new RuntimeException('El complemento no existe.');$resolver=new FiscalDocumentHistoricalTaxResolver($this->db);$issuer=$c->issuer_profile_id?(new \App\Services\Fiscal\FiscalIssuerResolver($this->db))->resolveById((int)$c->issuer_profile_id):(new \App\Services\Fiscal\FiscalIssuerResolver($this->db))->resolve();$receiver=$this->db->table('fiscal_profiles fp')->select('fp.*,tr.code tax_regime_code')->join('sat_tax_regimes tr','tr.id=fp.tax_regime_id','left')->where(['fp.client_id'=>$c->client_id,'fp.profile_type'=>'receiver'])->whereIn('fp.status',['active','ready'])->orderBy('fp.is_default','DESC')->get(1)->getRow();if(!$issuer)throw new RuntimeException('No existe un emisor fiscal con CSD vigente.');if(!$receiver)throw new RuntimeException('El cliente no tiene un perfil fiscal receptor vigente.');$payments=$this->db->table('payment_complement_payments p')->select('p.*,fm.sat_payment_form_code mapped_payment_form')->join('invoice_payments ip','ip.id=p.source_invoice_payment_id')->join('fiscal_payment_method_mappings fm','fm.payment_method_id=ip.payment_method_id AND fm.is_active=1','left')->where(['p.payment_complement_id'=>$id,'p.deleted'=>0])->get()->getResult();$out=['version'=>7,'complement_id'=>$id,'issue_date'=>(new FiscalIssueDateService())->formatForXml((string)$c->issue_date),'client_id'=>(int)$c->client_id,'issuer'=>['id'=>(int)$issuer->id,'certificate_id'=>(int)$issuer->certificate_id,'rfc'=>$issuer->rfc,'legal_name'=>$issuer->legal_name,'tax_regime_code'=>$issuer->tax_regime_code,'expedition_postal_code'=>$issuer->fiscal_postal_code],'receiver'=>['id'=>(int)$receiver->id,'rfc'=>$receiver->rfc,'legal_name'=>$receiver->legal_name,'tax_regime_code'=>$receiver->tax_regime_code,'fiscal_postal_code'=>$receiver->fiscal_postal_code,'cfdi_use_code'=>'CP01'],'payments'=>[],'totals'=>['MontoTotalPagos'=>'0.000000','TrasladosP'=>[],'RetencionesP'=>[]]];foreach($payments as$p){$docs=$this->db->table('payment_complement_documents')->where(['payment_complement_payment_id'=>$p->id,'deleted'=>0])->get()->getResult();$po=['id'=>(int)$p->id,'source_invoice_payment_id'=>(int)$p->source_invoice_payment_id,'FechaPago'=>$p->payment_date.'T12:00:00','FormaDePagoP'=>$p->payment_form_code?:$p->mapped_payment_form,'MonedaP'=>$p->currency_code?:'MXN','TipoCambioP'=>(string)$p->exchange_rate,'Monto'=>(string)$p->amount,'NumOperacion'=>$p->operation_number,'RfcEmisorCtaOrd'=>$p->ordering_bank_rfc,'NomBancoOrdExt'=>$p->ordering_bank_name,'CtaOrdenante'=>$p->ordering_account,'RfcEmisorCtaBen'=>$p->beneficiary_bank_rfc,'CtaBeneficiario'=>$p->beneficiary_account,'TipoCadPago'=>$p->payment_chain_type,'CertPago'=>$p->payment_certificate,'CadPago'=>$p->payment_chain,'SelloPago'=>$p->payment_signature,'DoctoRelacionado'=>[]];foreach($docs as$d){$h=$resolver->resolve((int)$d->fiscal_document_id);$taxes=$resolver->prorate($h,(string)$d->amount_paid,(string)$d->previous_balance);$dr=['IdDocumento'=>$d->document_uuid,'MonedaDR'=>$d->currency_dr?:'MXN','EquivalenciaDR'=>(string)($d->equivalence_dr?:'1.000000'),'NumParcialidad'=>(int)$d->installment_number,'ImpSaldoAnt'=>(string)$d->previous_balance,'ImpPagado'=>(string)$d->amount_paid,'ImpSaldoInsoluto'=>(string)$d->remaining_balance,'ObjetoImpDR'=>$h['tax_object_code'],'ImpuestosDR'=>['TrasladosDR'=>[],'RetencionesDR'=>[]]];foreach($taxes as$t){$n=['BaseDR'=>$t['base'],'ImpuestoDR'=>$t['tax_code'],'TipoFactorDR'=>$t['factor_type']];if($t['factor_type']!=='Exento'){$n['TasaOCuotaDR']=$t['rate_or_quota'];$n['ImporteDR']=$t['amount'];}$kind=$t['tax_type']==='withholding'?'RetencionesDR':'TrasladosDR';$dr['ImpuestosDR'][$kind][]=$n;$bucketName=$t['tax_type']==='withholding'?'RetencionesP':'TrasladosP';$key=implode('|',[$t['tax_code'],$t['factor_type'],(string)$t['rate_or_quota']]);$bucket=&$out['totals'][$bucketName];$bucket[$key]['BaseP']=FiscalDecimal::add($bucket[$key]['BaseP']??'0.000000',$t['base']);$bucket[$key]['ImporteP']=FiscalDecimal::add($bucket[$key]['ImporteP']??'0.000000',$t['amount']);$bucket[$key]['ImpuestoP']=$t['tax_code'];$bucket[$key]['TipoFactorP']=$t['factor_type'];$bucket[$key]['TasaOCuotaP']=$t['rate_or_quota'];unset($bucket);}$po['DoctoRelacionado'][]=$dr;}if(!$po['DoctoRelacionado'])throw new RuntimeException('El pago fiscal no contiene documentos derivados.');$out['payments'][]=$po;$out['totals']['MontoTotalPagos']=FiscalDecimal::add($out['totals']['MontoTotalPagos'],(string)$p->amount);}if(!$out['payments'])throw new RuntimeException('El complemento no contiene un pago administrativo derivado.');$out['sat_totals']=$this->satTotals($out['totals']);$out['xml']=(new PaymentComplementCfdiMaterializer())->materialize($out);$hash=$out;unset($hash['xml']);$out['sha256']=hash('sha256',json_encode($hash,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));return$out;}
 public function build(int$id,?int$actor=null):array{$out=$this->compose($id);$version=(int)($this->db->table('payment_complement_fiscal_snapshots')->selectMax('version','v')->where('payment_complement_id',$id)->get()->getRow()->v??0)+1;$this->db->table('payment_complement_fiscal_snapshots')->insert(['payment_complement_id'=>$id,'version'=>$version,'status'=>'preview','payload_json'=>json_encode($out,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'xml_content'=>$out['xml'],'sha256'=>$out['sha256'],'created_by'=>$actor,'created_at'=>get_current_utc_time()]);return$out;}
 private function satTotals(array$totals):array{$out=['MontoTotalPagos'=>$totals['MontoTotalPagos']];foreach($totals['TrasladosP']as$t){if($t['ImpuestoP']!=='002')continue;$suffix=$t['TipoFactorP']==='Exento'?'Exento':match((string)$t['TasaOCuotaP']){'0.160000'=>'16','0.080000'=>'8','0.000000'=>'0',default=>null};if($suffix===null)continue;$out['TotalTrasladosBaseIVA'.$suffix]=$t['BaseP'];if($suffix!=='Exento')$out['TotalTrasladosImpuestoIVA'.$suffix]=$t['ImporteP'];}foreach($totals['RetencionesP']as$t){$name=['001'=>'ISR','002'=>'IVA','003'=>'IEPS'][$t['ImpuestoP']]??null;if($name)$out['TotalRetenciones'.$name]=FiscalDecimal::add($out['TotalRetenciones'.$name]??'0.000000',$t['ImporteP']);}foreach($out as$key=>$value)$out[$key]=$this->satMoney((string)$value);return$out;} private function satMoney(string$value):string{$micros=FiscalDecimal::micros($value);if($micros<0)throw new RuntimeException('Los totales Pago 2.0 no pueden ser negativos.');$cents=intdiv($micros+5000,10000);return intdiv($cents,100).'.'.str_pad((string)($cents%100),2,'0',STR_PAD_LEFT);}
}